from manim import *

# Manim Community v0.19.1; no LaTeX required.
# Silent, text-led demonstration of genuine recursive backtracking.
# All candidate checks, failed calls, undo operations, and recursive returns
# are generated by the same solver used to produce the solutions.
import math

BG = '#101827'
WHITE2 = '#EDF2F7'
MUTED = '#AAB9CC'
GOLD = '#F5C451'
GREEN2 = '#42D49B'
RED2 = '#FF6677'
BLUE2 = '#65B6FF'
DARK_SQ = '#293D55'
LIGHT_SQ = '#54708D'


def solve_trace(n):
    """First solution, left-to-right DFS. Every check and return is recorded."""
    board = [-1] * n
    cols, d1, d2 = set(), set(), set()
    events = []
    stats = dict(calls=0, checks=0, rejected=0, placements=0, undos=0)

    def dfs(r):
        stats['calls'] += 1
        events.append(('enter', r, -1, tuple(board), None, stats.copy()))
        if r == n:
            events.append(('success', r, -1, tuple(board), None, stats.copy()))
            events.append(('return_true', r, -1, tuple(board), None, stats.copy()))
            return True
        for c in range(n):
            stats['checks'] += 1
            reason = 'column' if c in cols else 'main diagonal' if r-c in d1 else 'anti-diagonal' if r+c in d2 else None
            events.append(('check', r, c, tuple(board), reason, stats.copy()))
            if reason:
                stats['rejected'] += 1
                events.append(('reject', r, c, tuple(board), reason, stats.copy()))
                continue
            board[r] = c
            cols.add(c); d1.add(r-c); d2.add(r+c)
            stats['placements'] += 1
            events.append(('place', r, c, tuple(board), None, stats.copy()))
            if dfs(r+1):
                events.append(('return_true', r, c, tuple(board), None, stats.copy()))
                return True
            board[r] = -1
            cols.remove(c); d1.remove(r-c); d2.remove(r+c)
            stats['undos'] += 1
            events.append(('undo', r, c, tuple(board), None, stats.copy()))
        events.append(('dead_end', r, -1, tuple(board), None, stats.copy()))
        events.append(('return_false', r, -1, tuple(board), None, stats.copy()))
        return False

    dfs(0)
    return events, stats


class BacktrackingDetailed(Scene):
    def construct(self):
        self.camera.background_color = BG
        self.total_target = 625  # approx. 10 min 25 sec (scene times are calibrated)
        self.clock = 0.0
        self.heading('N-QUEENS: BACKTRACKING', 'Every failed placement, recursive return, and restored decision matters.')
        self.info('We build a solution one row at a time. A conflict is rejected immediately.\nIf a later row cannot be filled, recursion returns and the last queen is removed.', 12)
        self.info('ALGORITHM: CHOOSE  >  CHECK  >  EXPLORE  >  UNDO\nGreen = safe placement   |   Red = conflict   |   Gold = candidate under test', 10)
        self.section(4, 'PART 1  /  N = 4', 'Full search trace: every check, failure, undo, and return.', 5)
        self.play_case(4, 230, show_all=True)
        self.section(5, 'PART 2  /  N = 5', 'A larger board, exactly the same recursive algorithm.', 5)
        self.play_case(5, 150, show_all=True)
        self.section(8, 'PART 3  /  N = 8', 'All search events are computed; repetitive checks are compressed visually.', 5)
        self.play_case(8, 155, show_all=False)
        self.info('WHY IT WORKS\nA queen is placed only if its column and both diagonals are free.\nUndo restores the exact state that existed before the failed recursive call.', 10)
        self.info('COMPLEXITY\nThe search has factorial worst-case growth; constant-time occupancy checks\nuse O(N) auxiliary memory, including the recursion stack.', 10)
        self.info('TAKEAWAY\nBacktracking does not guess the answer. It systematically explores safe prefixes,\nreturns from dead ends, and never expands an already invalid prefix.', 10)
        if self.clock < self.total_target:
            self.tick(self.total_target-self.clock)

    def tick(self, secs):
        self.wait(secs)
        self.clock += secs

    def play_t(self, *animations, run_time=1):
        self.play(*animations, run_time=run_time)
        self.clock += run_time

    def txt(self, text, size=27, color=WHITE2, maxw=12.0):
        obj = Text(text, font_size=size, color=color, line_spacing=1.18)
        if obj.width > maxw:
            obj.scale_to_fit_width(maxw)
        return obj

    def heading(self, title, subtitle):
        t = self.txt(title, 46, GOLD).to_edge(UP, buff=1.65)
        s = self.txt(subtitle, 25, MUTED).next_to(t, DOWN, buff=.45)
        self.play_t(FadeIn(t, shift=UP*.3), FadeIn(s), run_time=1.2)
        self.tick(5)
        self.play_t(FadeOut(t), FadeOut(s), run_time=.6)

    def info(self, text, seconds):
        lines = text.split('\n')
        group = VGroup(*[self.txt(line, 29 if i == 0 else 24, GOLD if i == 0 else WHITE2, 11.7) for i,line in enumerate(lines)])
        group.arrange(DOWN, buff=.42).move_to(ORIGIN)
        self.play_t(FadeIn(group), run_time=.6)
        self.tick(max(0, seconds-1.2))
        self.play_t(FadeOut(group), run_time=.6)

    def section(self, n, title, desc, seconds):
        group = VGroup(self.txt(title, 44, GOLD), self.txt(desc, 25, MUTED, 11))
        group.arrange(DOWN, buff=.45).move_to(ORIGIN)
        self.play_t(FadeIn(group, shift=UP*.3), run_time=.6)
        self.tick(seconds-1.2)
        self.play_t(FadeOut(group), run_time=.6)

    def make_board(self, n):
        size = 4.55 / n
        cells = VGroup()
        for r in range(n):
            for c in range(n):
                sq = Square(side_length=size, stroke_width=1, stroke_color='#8FA6BD',
                            fill_color=LIGHT_SQ if (r+c)%2 == 0 else DARK_SQ, fill_opacity=1)
                sq.move_to([(c-(n-1)/2)*size, ((n-1)/2-r)*size, 0])
                cells.add(sq)
        board = VGroup(cells).move_to(LEFT*3.65 + DOWN*.05)
        return cells, size

    def play_case(self, n, seconds, show_all):
        events, final_stats = solve_trace(n)
        cells, size = self.make_board(n)
        board_center = cells.get_center()
        title = self.txt(f'N = {n}   |   RECURSIVE DFS', 29, GOLD).to_edge(UP, buff=.28)
        desc = self.txt('Try columns left to right; one queen per row.', 21, MUTED).next_to(title, DOWN, buff=.15)
        status = self.txt('Preparing recursive trace...', 23, WHITE2, 6.4).move_to(RIGHT*2.35+UP*1.1)
        details = self.txt('Waiting for the first call', 21, MUTED, 6.2).move_to(RIGHT*2.35+DOWN*.05)
        stats_txt = self.txt('Calls: 0   Checks: 0', 20, BLUE2, 6.4).move_to(RIGHT*2.35+DOWN*1.5)
        labels = VGroup(*[self.txt(str(i+1), 18, MUTED).move_to(board_center+RIGHT*((i-(n-1)/2)*size)+UP*(n*size/2+.25)) for i in range(n)])
        labels.add(*[self.txt(str(i+1), 18, MUTED).move_to(board_center+UP*((n-1)/2-i)*size+LEFT*(n*size/2+.25)) for i in range(n)])
        queens = VGroup()
        self.play_t(FadeIn(cells), FadeIn(labels), FadeIn(title), FadeIn(desc), FadeIn(status), FadeIn(details), FadeIn(stats_txt), run_time=1.2)
        start = self.clock
        # Show every event for N=4 and N=5. For N=8, compress the repetitive checks
        # while retaining all recorded events and displaying live cumulative counters.
        selected = list(range(len(events)))
        if not show_all:
            selected = [i for i,e in enumerate(events) if e[0] in ('enter','place','undo','dead_end','return_false','success','return_true')]
            # retain periodic checks and rejected candidates to show why branches fail
            selected += [i for i,e in enumerate(events) if e[0] == 'reject' and i%13 == 0]
            selected = sorted(set(selected))
        available = max(10, seconds-12)
        per = min(.85, available / max(1, len(selected)))
        current_board = None
        for idx in selected:
            kind,r,c,arr,reason,stats = events[idx]
            if current_board != arr:
                for q in queens:
                    self.remove(q)
                queens = VGroup()
                for rr,cc in enumerate(arr):
                    if cc >= 0:
                        q = self.txt('Q', min(36, int(size*65)), GREEN2)
                        q.move_to(cells[rr*n+cc].get_center())
                        queens.add(q)
                        self.add(q)
                current_board = arr
            messages = {
                'enter': f'CALL solve(row={r+1})' if r<n else 'BASE CASE: all queens placed',
                'check': f'CHECK row {r+1}, column {c+1}',
                'reject': f'REJECT ({r+1}, {c+1})',
                'place': f'PLACE queen at ({r+1}, {c+1})',
                'undo': f'UNDO queen at ({r+1}, {c+1})',
                'dead_end': f'DEAD END at row {r+1}',
                'return_false': f'RETURN false from row {r+1}',
                'success': 'SUCCESS: valid arrangement found',
                'return_true': f'RETURN true from row {r+1}' if r<n else 'RETURN true from base case'
            }
            explain = {
                'enter': 'A new recursive call begins. Try columns in order.',
                'check': 'Test column and both diagonal constraints.',
                'reject': f'Conflict detected: {reason}. Skip this square.',
                'place': 'Safe candidate: update occupancy, then recurse.',
                'undo': 'Deeper recursion failed: remove queen and restore occupancy.',
                'dead_end': 'No safe columns remain. The current branch cannot succeed.',
                'return_false': 'Return to the caller so it can try the next column.',
                'success': 'One queen occupies each row, column, and diagonal safely.',
                'return_true': 'Success propagates back through the recursion stack.'
            }
            new_status = self.txt(messages[kind], 23, RED2 if kind in ('reject','undo','dead_end','return_false') else GREEN2 if kind in ('success','return_true','place') else GOLD, 6.1).move_to(status)
            new_detail = self.txt(explain[kind], 19, MUTED, 6.1).move_to(details)
            new_stats = self.txt(f"Calls: {stats['calls']}   Checks: {stats['checks']}\nRejected: {stats['rejected']}   Undos: {stats['undos']}", 20, BLUE2, 6.2).move_to(stats_txt)
            self.remove(status, details, stats_txt)
            status, details, stats_txt = new_status, new_detail, new_stats
            self.add(status, details, stats_txt)
            if c >= 0 and kind in ('check','reject','place','undo'):
                sq = cells[r*n+c]
                flash = sq.copy().set_fill(RED2 if kind in ('reject','undo') else GREEN2 if kind=='place' else GOLD, opacity=.6)
                flash.set_stroke(width=0)
                self.add(flash)
                self.tick(per*.62)
                self.remove(flash)
                self.tick(per*.38)
            else:
                self.tick(per)
        arrangement = [v+1 for v in next(e[3] for e in events if e[0]=='success')]
        summary = self.txt(f"First solution: {arrangement}\nTotal calls: {final_stats['calls']}  |  Rejections: {final_stats['rejected']}  |  Undos: {final_stats['undos']}", 23, GREEN2, 6.3).move_to(RIGHT*2.35+DOWN*2.35)
        self.play_t(FadeIn(summary), run_time=.5)
        elapsed = self.clock-start
        if elapsed < seconds-1:
            self.tick(seconds-1-elapsed)
        self.play_t(*[FadeOut(x) for x in (cells,labels,title,desc,status,details,stats_txt,queens,summary)], run_time=1)

if __name__ == '__main__':
    for n in (4,5,8):
        ev,st=solve_trace(n)
        print(n, len(ev), st)
